-- Carbohydrate and fat join calories and protein. Catalog values are per 100 g like the others;
-- entries store grams, and stay NULL for entries logged before this or typed without them.
ALTER TABLE foods
    ADD COLUMN carbs_per_100g NUMERIC(4,1) NOT NULL DEFAULT 0 CHECK (carbs_per_100g BETWEEN 0 AND 100),
    ADD COLUMN fat_per_100g   NUMERIC(4,1) NOT NULL DEFAULT 0 CHECK (fat_per_100g BETWEEN 0 AND 100);

ALTER TABLE food_entries
    ADD COLUMN carbs_g NUMERIC(5,1) CHECK (carbs_g BETWEEN 0 AND 1000),
    ADD COLUMN fat_g   NUMERIC(5,1) CHECK (fat_g BETWEEN 0 AND 1000);

